export async function init() {
  if (inPortfolio()) {
    const fmtN = (n) => Number(n || 0).toLocaleString();
    return initPicker(apiBase(), [
      { h: 'Magnets', td: (r) => `${fmtN(r.magnets.active)}<span style="color:var(--color-text-subtle,#6C7C9A)">/${fmtN(r.magnets.total)}</span>` },
      { h: 'Leads · wk', td: (r) => fmtN(r.leads.this_week) },
    ], { emptyMsg: 'No client orgs yet. Create one under Clients first.' });
  }
  consumeReturnParams();
  await load();
}

// Every OAuth provider (not callrail — no redirect flow, it's a pasted key,
// which is exactly what having no `connect` section in its descriptor means).
const PROVIDER_LABEL = Object.fromEntries(
  Object.values(PROVIDERS).filter((p) => p.connect).map((p) => [p.slug, p.label]),
);

/** OAuth outcome rides the search string (survives the hash router). */
function consumeReturnParams() {
  try {
    const sp = new URLSearchParams(window.location.search);
    const connected = sp.get('connected');
    const errorProvider = sp.get('error') ? (sp.get('provider') || 'google_ads') : null; // pre-explicit-provider callbacks defaulted to Ads
    if (connected && PROVIDER_LABEL[connected]) {
      toast(`${PROVIDER_LABEL[connected]} connected.`, 'success');
      if (PROVIDERS[connected]?.picker) state.autoOpenPicker = connected; // …and it has accounts to choose
    } else if (errorProvider) {
      toast(`${PROVIDER_LABEL[errorProvider] || errorProvider} connection failed (${sp.get('error')}).`, 'error');
    } else {
      return;
    }
    window.history.replaceState(null, '', window.location.pathname + window.location.hash);
  } catch { /* cosmetic only */ }
}

async function load() {
  const body = document.getElementById('intg-body');
  try {
    const res = await fetch(`${apiBase()}/m5t/v5/integrations`);
    if (res.status === 403) {
      state.denied = true;
      if (body) body.innerHTML = `<div class="dashboard-card intg-card"><div class="card-body">${emptyState('lock', 'Integrations are managed by workspace admins.')}</div></div>`;
      return;
    }
    const data = await res.json();
    if (!data.ok) throw new Error(data.error || 'load failed');
    state.providers = data.data.providers;
    state.configured = data.data.configured;
    renderBody();
  } catch (e) {
    if (body) body.innerHTML = `<div class="dashboard-card intg-card"><div class="card-body">${emptyState('error', 'Could not load integrations.')}</div></div>`;
  }
}

/** Card for a metric provider (Google Ads / Google Analytics) — one body, two
 * descriptors. Same state machine both ways: not-configured → not-connected →
 * connected-healthy → connected-broken. */
function metricProviderCard(p) {
  const c = p.card;
  const org = orgGuid();
  const conns = state.providers?.[p.slug] || [];
  const conn = conns.find((x) => x.owner_guid === org) || conns[0] || null;
  const configured = !!state.configured?.[p.slug];

  let pill = `<span class="intg-state">Not connected</span>`;
  let desc = c.idleDesc;
  let actions = '';

  if (!configured) {
    pill = `<span class="intg-state">Not available yet</span>`;
    desc = `${p.label} reporting is being set up for this platform.`;
  } else if (!conn) {
    actions = `<button type="button" class="intg-btn primary" id="${c.ids.connect}"><span class="material-symbols-outlined" aria-hidden="true">link</span>Connect</button>`;
  } else {
    const n = c.reachableCount(conn.external_account);
    const healthy = conn.connect_status === 'ACTIVE';
    if (healthy) {
      pill = `<span class="intg-state on"><span class="material-symbols-outlined" aria-hidden="true">check</span>Connected</span>`;
      desc = n ? c.reachDesc(n) : c.noneDesc;
      actions = `
        <button type="button" class="intg-btn" id="${c.ids.choose}"><span class="material-symbols-outlined" aria-hidden="true">checklist</span>${c.chooseLabel}</button>
        <button type="button" class="intg-btn" id="${c.ids.sync}"><span class="material-symbols-outlined" aria-hidden="true">sync</span>Sync now</button>
        <button type="button" class="intg-btn danger" id="${c.ids.disconnect}"><span class="material-symbols-outlined" aria-hidden="true">link_off</span>Disconnect</button>`;
    } else {
      pill = `<span class="intg-state warn"><span class="material-symbols-outlined" aria-hidden="true">priority_high</span>${esc(conn.connect_status === 'NEEDS_REAUTH' ? 'Reconnect needed' : 'Connection error')}</span>`;
      desc = 'The connection stopped working. Reconnect to resume daily metric refreshes.';
      actions = `
        <button type="button" class="intg-btn primary" id="${c.ids.connect}"><span class="material-symbols-outlined" aria-hidden="true">link</span>Reconnect</button>
        <button type="button" class="intg-btn danger" id="${c.ids.disconnect}"><span class="material-symbols-outlined" aria-hidden="true">link_off</span>Disconnect</button>`;
    }
  }

  return integrationCardHTML({
    tint: c.tint, icon: c.icon, name: p.label, sub: c.sub,
    pill, actions, desc, walkthrough: walkthroughHTML(p.slug),
    bodyExtra: `<div id="${c.ids.panel}" style="display:none"></div>`,
  });
}

