/** Every button on a metric provider's card, wired to the shared handlers. */
function wireMetricProvider(p) {
  const ids = p.card.ids;
  document.getElementById(ids.connect)?.addEventListener('click', () => connectProvider(p));
  document.getElementById(ids.sync)?.addEventListener('click', () => syncProvider(p));
  document.getElementById(ids.disconnect)?.addEventListener('click', () => disconnectProvider(p));
  document.getElementById(ids.choose)?.addEventListener('click', () => openProviderPicker(p));
}

function renderBody() {
  const body = document.getElementById('intg-body');
  if (!body) return;
  body.innerHTML = metricProviderCard(PROVIDERS.google_ads) + calendlyCard() + callrailCard() + metricProviderCard(PROVIDERS.google_analytics);

  wireMetricProvider(PROVIDERS.google_ads);
  document.getElementById('intg-c-connect')?.addEventListener('click', () => connectProvider(PROVIDERS.calendly));
  document.getElementById('intg-c-disconnect')?.addEventListener('click', () => disconnectProvider(PROVIDERS.calendly));
  document.getElementById('intg-r-connect')?.addEventListener('click', openCallrailSetup);
  document.getElementById('intg-r-sync')?.addEventListener('click', syncCallrail);
  document.getElementById('intg-r-disconnect')?.addEventListener('click', () => disconnectProvider(PROVIDERS.callrail));
  wireMetricProvider(PROVIDERS.google_analytics);

  // Just came back from a provider's OAuth redirect: open that provider's
  // picker so the next step (choose what feeds reporting) is already in front
  // of you. Only providers that have one — Calendly has nothing to choose.
  const returned = state.autoOpenPicker ? PROVIDERS[state.autoOpenPicker] : null;
  if (returned?.picker && document.getElementById(returned.card.ids.choose)) {
    openProviderPicker(returned);
  }
  state.autoOpenPicker = false;
}

// ── sub-account picker: choose what feeds reporting ──────────────────────────
// Ad accounts (Google Ads) and GA4 properties (Google Analytics) are the same
// panel: load the reachable list, check the linked ones, POST the selection.
async function openProviderPicker(p) {
  const pk = p.picker;
  const panel = document.getElementById(p.card.ids.panel);
  if (!panel) return;
  panel.style.display = '';
  panel.innerHTML = alertHTML(pk.loading);
  try {
    const res = await fetch(`${apiBase()}/m5t/v5/integrations/${p.slug}/${pk.path}`);
    const data = await res.json();
    if (!data.ok) throw new Error(data.error || 'load failed');
    renderProviderPicker(p, data.data[pk.itemsField] || [], new Set(data.data.linked || []));
  } catch (e) {
    panel.innerHTML = alertHTML(pk.loadError, 'error');
  }
}

function renderProviderPicker(p, items, linked) {
  const pk = p.picker;
  const panel = document.getElementById(p.card.ids.panel);
  if (!panel) return;

  const rows = items.map((it) => {
    const disabled = pk.rowDisabled(it);
    const badge = pk.rowBadge(it);
    const checked = linked.has(it.id) && !disabled;
    return `
      <label class="intg-acct${disabled ? ' disabled' : ''}">
        <input type="checkbox" data-${pk.dataAttr}="${esc(it.id)}" ${checked ? 'checked' : ''} ${disabled ? 'disabled' : ''}>
        <span style="min-width:0">
          <span class="intg-acct__name">${esc(it.name || pk.namePrefix + it.id)}</span>
          <div class="intg-acct__id">${esc(it.id)}</div>
        </span>
        ${badge ? `<span class="intg-acct__badge">${esc(badge)}</span>` : '<span></span>'}
      </label>`;
  }).join('');

  panel.innerHTML = `
    <div class="intg-picker">
      <div class="intg-picker__head">
        <span>${pk.heading}</span>
        <span style="font-weight:500">${items.filter((it) => !pk.rowDisabled(it)).length} selectable</span>
      </div>
      <div class="intg-picker__list">
        ${rows || `<div class="intg-picker__empty">${pk.emptyMsg}</div>`}
      </div>
      <div class="intg-picker__foot">
        <button type="button" class="intg-btn" id="${pk.ids.cancel}">Cancel</button>
        <button type="button" class="intg-btn primary" id="${pk.ids.save}"><span class="material-symbols-outlined" aria-hidden="true">save</span>Save</button>
      </div>
    </div>`;

  document.getElementById(pk.ids.cancel)?.addEventListener('click', () => { panel.style.display = 'none'; });
  document.getElementById(pk.ids.save)?.addEventListener('click', () => saveProviderPicker(p));
}

async function saveProviderPicker(p) {
  const pk = p.picker;
  const panel = document.getElementById(p.card.ids.panel);
  const ids = [...(panel?.querySelectorAll(`input[data-${pk.dataAttr}]:checked`) || [])].map((el) => el.dataset[pk.datasetKey]);
  const btn = document.getElementById(pk.ids.save);
  if (btn) btn.disabled = true;
  try {
    const res = await fetch(`${apiBase()}/m5t/v5/integrations/${p.slug}/${pk.path}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ [pk.saveField]: ids }),
    });
    const data = await res.json();
    if (!data.ok) throw new Error(data.error || 'save failed');
    toast(pk.savedToast(data.data.linked), 'success');
    if (panel) panel.style.display = 'none';
    load();
  } catch (e) {
    toast(pk.saveError, 'error');
    if (btn) btn.disabled = false;
  }
}

// ── actions ──────────────────────────────────────────────────────────────────
/** Start a provider's OAuth flow: the API hands back an authorize URL to
 * follow. Used by Google Ads, Google Analytics and Calendly — one body, so the
 * error handling below cannot drift between them again. */
async function connectProvider(p) {
  if (state.busy) return;
  state.busy = true;
  try {
    const res = await fetch(`${apiBase()}/m5t/v5/integrations/${p.slug}/connect`);
    const data = await res.json();
    if (!data.ok || !data.data?.url) throw new Error(data.error || 'connect failed');
    window.location.href = data.data.url;
  } catch (e) {
    // Surface the real reason (e.g. "Google Ads is not configured on this
    // server") instead of a hardcoded generic string — a not-configured
    // server-side env var previously looked identical to a real network
    // failure, only distinguishable by digging through coreMeter by hand.
    // This is also what a click on Connect looked like when it silently "did
    // nothing": the card's own gate hides the button when !configured, but a
    // stale render or a race with that check landing late would otherwise
    // show only a vague toast with no real cause.
    // This single line is the whole point of the shared body: 0dcf1f4 fixed it
    // for Google Ads and Calendly and missed the copy-pasted GA twin.
    toast(e.message || p.connect.fallbackError, 'error');
    state.busy = false;
  }
}

/** Pull metrics now for a provider whose card offers Sync now (the two Google
 * ones). Per-sub-account errors come back in the response, not as a throw. */
async function syncProvider(p) {
  if (state.busy) return;
  state.busy = true;
  const btn = document.getElementById(p.card.ids.sync);
  if (btn) btn.disabled = true;
  try {
    const res = await fetch(`${apiBase()}/m5t/v5/integrations/${p.slug}/sync`, { method: 'POST' });
    const data = await res.json();
    if (!data.ok) throw new Error(data.error || 'sync failed');
    const items = data.data?.connections?.[0]?.[p.sync.itemsField] || [];
    const failed = items.filter((it) => it.error).length;
    toast(failed ? p.sync.failedToast(failed) : 'Metrics synced.', failed ? 'warning' : 'success');
  } catch (e) {
    toast('Sync failed.', 'error');
  } finally {
    state.busy = false;
    if (btn) btn.disabled = false;
    load();
  }
}

/** Drop a provider's connection after confirming. Same shape for all four
 * providers — only the confirm question and the success toast differ. */
async function disconnectProvider(p) {
  if (state.busy) return;
  if (!window.confirm(p.disconnect.confirm)) return;
  state.busy = true;
  try {
    const res = await fetch(`${apiBase()}/m5t/v5/integrations/${p.slug}`, { method: 'DELETE' });
    const data = await res.json().catch(() => ({}));
    if (!data.ok) throw new Error(data.error || 'disconnect failed');
    toast(p.disconnect.toast, 'success');
  } catch (e) {
    toast('Disconnect failed.', 'error');
  } finally {
    state.busy = false;
    load();
  }
}

// ── CallRail: paste-key setup (no OAuth exists for their API) ────────────────
function openCallrailSetup() {
  const panel = document.getElementById('intg-r-setup');
  if (!panel) return;
  panel.style.display = '';
  panel.innerHTML = `
    <div class="intg-picker">
      <div class="intg-picker__head"><span>Connect CallRail</span></div>
      <div class="intg-form">
        <div>
          <label for="intg-r-key">API key</label>
          <input class="intg-input" id="intg-r-key" type="password" autocomplete="off" spellcheck="false" placeholder="Paste your CallRail API v3 key">
          <p class="intg-hint">Create one in CallRail under Integrations, then Data access, then API keys. Read-only is fine for calls; Allow Writes lets us register call sync for you.</p>
        </div>
        <div id="intg-r-pickers" hidden>
          <label for="intg-r-account">Account</label>
          <select class="intg-select" id="intg-r-account"></select>
          <label for="intg-r-company" style="margin-top:8px;display:block">Company (your client)</label>
          <select class="intg-select" id="intg-r-company"></select>
        </div>
        <p class="intg-hint" id="intg-r-status" role="status"></p>
      </div>
      <div class="intg-picker__foot">
        <button type="button" class="intg-btn" id="intg-r-cancel">Cancel</button>
        <button type="button" class="intg-btn primary" id="intg-r-continue">Continue</button>
      </div>
    </div>`;
  document.getElementById('intg-r-cancel')?.addEventListener('click', () => { panel.style.display = 'none'; });
  document.getElementById('intg-r-continue')?.addEventListener('click', callrailContinue);
  document.getElementById('intg-r-key')?.focus();
}

const rStatus = (msg) => { const el = document.getElementById('intg-r-status'); if (el) el.textContent = msg; };

async function callrailContinue() {
  const btn = document.getElementById('intg-r-continue');
  const key = document.getElementById('intg-r-key')?.value.trim() || '';
  const pickers = document.getElementById('intg-r-pickers');
  if (!key) { rStatus('Paste an API key first.'); return; }

  // Second click (pickers visible) = finalize.
  if (pickers && !pickers.hidden) return callrailSave(key);

  if (btn) btn.disabled = true;
  rStatus('Checking the key with CallRail…');
  try {
    const res = await fetch(`${apiBase()}/m5t/v5/integrations/callrail/validate`, {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ api_key: key }),
    });
    const data = await res.json();
    if (!data.ok) { rStatus(data.error || 'CallRail rejected that key.'); return; }
    const accounts = data.data.accounts || [];
    const acctSel = document.getElementById('intg-r-account');
    if (acctSel) {
      acctSel.innerHTML = accounts.map((a) => `<option value="${esc(a.id)}">${esc(a.name)}</option>`).join('');
      acctSel.onchange = () => loadCallrailCompanies(key, acctSel.value);
    }
    if (pickers) pickers.hidden = false;
    if (btn) btn.innerHTML = `<span class="material-symbols-outlined" aria-hidden="true">save</span>Save`;
    rStatus('');
    await loadCallrailCompanies(key, accounts[0]?.id);
  } catch (e) {
    rStatus('Could not reach CallRail. Try again.');
  } finally {
    if (btn) btn.disabled = false;
  }
}

async function loadCallrailCompanies(key, accountId) {
  const sel = document.getElementById('intg-r-company');
  if (!sel || !accountId) return;
  sel.innerHTML = `<option value="">Loading companies…</option>`;
  try {
    const res = await fetch(`${apiBase()}/m5t/v5/integrations/callrail/companies`, {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ api_key: key, account_id: accountId }),
    });
    const data = await res.json();
    const companies = data.ok ? (data.data.companies || []) : [];
    sel.innerHTML = companies.length
      ? companies.map((c) => `<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('')
      : `<option value="">No active companies in this account</option>`;
  } catch {
    sel.innerHTML = `<option value="">Could not load companies</option>`;
  }
}

async function callrailSave(key) {
  const btn = document.getElementById('intg-r-continue');
  const accountId = document.getElementById('intg-r-account')?.value || '';
  const companyId = document.getElementById('intg-r-company')?.value || '';
  if (!companyId) { rStatus('Pick the company this workspace tracks.'); return; }
  if (btn) btn.disabled = true;
  rStatus('Connecting…');
  try {
    const res = await fetch(`${apiBase()}/m5t/v5/integrations/callrail`, {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ api_key: key, account_id: accountId, company_id: companyId }),
    });
    const data = await res.json();
    if (!data.ok) throw new Error(data.error || 'connect failed');
    toast(data.data?.webhook_state === 'active'
      ? 'CallRail connected. Call sync is on.'
      : 'CallRail connected. Call sync setup needs attention; see the card.', 'success');
    load();
  } catch (e) {
    rStatus('Could not connect. Check the key and try again.');
    if (btn) btn.disabled = false;
  }
}

async function syncCallrail() {
  if (state.busy) return;
  state.busy = true;
  const btn = document.getElementById('intg-r-sync');
  if (btn) btn.disabled = true;
  try {
    const res = await fetch(`${apiBase()}/m5t/v5/integrations/callrail/sync?days=7`, { method: 'POST' });
    const data = await res.json();
    if (!data.ok) throw new Error(data.error || 'sync failed');
    const c = data.data?.connections?.[0] || {};
    toast(c.error ? 'Sync finished with errors.' : `Sync done. ${c.processed || 0} new call${(c.processed || 0) === 1 ? '' : 's'} recorded.`, c.error ? 'warning' : 'success');
  } catch (e) {
    toast('Sync failed.', 'error');
  } finally {
    state.busy = false;
    if (btn) btn.disabled = false;
    load();
  }
}

